require_once __DIR__ . '/../includes/functions.php'; require_login();$user=current_user();$status=(string)($_GET['status']??'all');if(!in_array($status,['all','pending','completed'],true))$status='all';$subjectFilter=filter_input(INPUT_GET,'subject_id',FILTER_VALIDATE_INT)?:0;
$sql="SELECT t.*,s.name subject_name FROM study_tasks t LEFT JOIN subjects s ON s.id=t.subject_id AND s.user_id=t.user_id WHERE t.user_id=?";$params=[$user['id']];if($status!=='all'){$sql.=" AND t.status=?";$params[]=$status;}if($subjectFilter){$sql.=" AND t.subject_id=?";$params[]=$subjectFilter;}$sql.=" ORDER BY (t.status='completed'), (t.due_date IS NULL), t.due_date ASC, FIELD(t.priority,'high','medium','low'), t.created_at DESC";
$stmt=db()->prepare($sql);$stmt->execute($params);$tasks=$stmt->fetchAll();$stmt=db()->prepare('SELECT id,name FROM subjects WHERE user_id=? ORDER BY name');$stmt->execute([$user['id']]);$subjects=$stmt->fetchAll();
$pageTitle='My tasks';$activePage='tasks';require __DIR__.'/../includes/header.php';
?>
