<?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Subject</th><th>Deadline</th><th>Priority</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($tasks as $t): $isOverdue=$t['status']==='pending'&&$t['due_date']&&$t['due_date']<date('Y-m-d'); ?><tr data-task-row data-status="<?= e($t['status']) ?>"><td><span class="table-title"><?= e($t['title']) ?></span><?php if($t['description']): ?><span class="table-sub"><?= e(mb_strimwidth($t['description'],0,72,'…')) ?></span><?php endif; ?></td><td><?= e($t['subject_name']?:'—') ?></td><td><?= $t['due_date']?e(date('M j, Y',strtotime($t['due_date']))):'No deadline' ?><?php if($isOverdue): ?><span class="table-sub" style="color:var(--error)">Overdue</span><?php endif; ?></td><td><span class="pill pill-<?= e($t['priority']) ?>"><?= e(task_priority_label($t['priority'])) ?></span></td><td><span class="pill <?= $t['status']==='completed'?'pill-completed':($isOverdue?'pill-overdue':'') ?>"><?= $t['status']==='completed'?'Completed':($isOverdue?'Overdue':'Pending') ?></span></td><td><div class="table-actions"><form class="inline-form" method="post" action="task_action.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="icon-action" title="<?= $t['status']==='completed'?'Mark pending':'Mark completed' ?>" aria-label="<?= $t['status']==='completed'?'Mark pending':'Mark completed' ?>"><?= $t['status']==='completed'?'↶':'✓' ?></button></form><a class="icon-action" href="add_task.php?id=<?= (int)$t['id'] ?>" title="Edit task" aria-label="Edit task">✎</a><form class="inline-form" method="post" action="task_action.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="task_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="action" value="delete"><button class="icon-action delete" title="Delete task" aria-label="Delete task" data-confirm="Permanently delete this task?">×</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><div class="filter-empty" id="filterEmpty" hidden>No tasks match your search or filter.</div><?php endif; ?></section>
